import Link from "next/link";
import { ArrowUpRight, MessagesSquare, PenSquare } from "lucide-react";
import NachrichtenThread from "@/components/Portal/NachrichtenThread";
import { Badge, Karte, Leer, SeitenKopf } from "@/components/Portal/ui";
import { cn } from "@/components/ui/cn";
import { portalNutzer, laden, istAdmin } from "@/lib/plattform/server/seite";
import { backend } from "@/lib/plattform/backend";
import { BEZUG_ARTEN, BEZUG_LABEL } from "@/lib/plattform/konstanten";
import { relativ } from "@/lib/plattform/format";

export const metadata = { title: "Nachrichten" };

export default async function Nachrichten({ searchParams }) {
  const n = await portalNutzer();
  const sp = await searchParams;
  const b = backend();
  const admin = istAdmin(n);
  const filter = sp?.filter === "ungelesen" ? "ungelesen" : "alle";

  let [art, id] = typeof sp?.bezug === "string" ? sp.bezug.split(":") : [];
  if (!BEZUG_ARTEN.includes(art)) [art, id] = [];

  // Thread zuerst laden (markiert als gelesen), dann die Liste mit aktuellen Zählern
  const thread = art ? await laden(() => b.nachrichten(n, art, id)) : null;
  let threads = await b.nachrichtenThreads(n);
  if (filter === "ungelesen") threads = threads.filter((t) => t.ungelesen || (art && t.bezugArt === art && t.bezugId === id));
  const aktiv = thread || (!admin ? await b.nachrichten(n, "nutzer", n.id) : null);
  const aktivArt = thread ? art : "nutzer";
  const aktivId = thread ? id : n.id;

  return (
    <div>
      <SeitenKopf
        eyebrow="Nachrichten"
        titel={admin ? "Nachrichten & Postfach" : "Nachrichten"}
        text={admin ? "Alle Unterhaltungen mit Nutzern – Antworten erscheinen sofort in deren Portal." : "Ihr direkter Draht zum Backoffice – zu jeder Anfrage, Fläche und jedem Projekt."}
      />
      <div className="grid gap-6 lg:grid-cols-[minmax(0,380px)_minmax(0,1fr)]">
        <Karte innen="p-2" className="self-start">
          <div className="flex gap-1.5 px-2 pb-2 pt-1">
            {[["alle", "Alle"], ["ungelesen", "Ungelesen"]].map(([k, v]) => (
              <Link key={k} href={`/portal/nachrichten?filter=${k}${art ? `&bezug=${art}:${id}` : ""}`} aria-current={filter === k ? "page" : undefined} className={cn("rounded-full px-3 py-1.5 text-[13px] font-semibold", filter === k ? "bg-navy-900 text-white" : "text-ink-600 hover:bg-ink-100")}>
                {v}
              </Link>
            ))}
          </div>
          <ul className="max-h-[70vh] space-y-0.5 overflow-y-auto">
            {!admin && (
              <li>
                <Link href={`/portal/nachrichten?bezug=nutzer:${n.id}`} className={cn("flex items-center gap-3 rounded-2xl p-3", aktivArt === "nutzer" && aktivId === n.id ? "bg-ov-50 ring-1 ring-ov-200" : "hover:bg-sand-50")}>
                  <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-ov-600 text-white"><PenSquare aria-hidden="true" className="h-4 w-4" /></span>
                  <span className="min-w-0">
                    <span className="block text-[14px] font-semibold text-ink-900">Allgemeine Nachricht</span>
                    <span className="block text-[12.5px] text-ink-500">Frage ohne Bezug an das Backoffice</span>
                  </span>
                </Link>
              </li>
            )}
            {threads
              .filter((t) => admin || !(t.bezugArt === "nutzer" && t.bezugId === n.id))
              .map((t) => {
                const ist = t.bezugArt === aktivArt && t.bezugId === aktivId;
                return (
                  <li key={`${t.bezugArt}:${t.bezugId}`}>
                    <Link href={`/portal/nachrichten?bezug=${t.bezugArt}:${t.bezugId}${filter === "ungelesen" ? "&filter=ungelesen" : ""}`} aria-current={ist ? "true" : undefined} className={cn("block rounded-2xl p-3", ist ? "bg-ov-50 ring-1 ring-ov-200" : "hover:bg-sand-50")}>
                      <span className="flex items-center justify-between gap-2">
                        <span className="text-[11.5px] font-semibold uppercase tracking-wider text-ink-400">{BEZUG_LABEL[t.bezugArt]}{admin && t.gegenueber ? ` · ${t.gegenueber}` : ""}</span>
                        <span className="shrink-0 text-[11.5px] text-ink-400">{relativ(t.letzte.am)}</span>
                      </span>
                      <span className="mt-0.5 flex items-center gap-2">
                        <span className={cn("min-w-0 flex-1 truncate text-[14px]", t.ungelesen ? "font-bold text-ink-900" : "font-semibold text-ink-800")}>{t.titel}</span>
                        {t.ungelesen > 0 && <Badge ton="ok" className="px-2 py-0.5">{t.ungelesen}</Badge>}
                      </span>
                      <span className="mt-0.5 line-clamp-2 block text-[13px] leading-snug text-ink-500">{t.letzte.text}</span>
                    </Link>
                  </li>
                );
              })}
            {threads.length === 0 && admin && <li className="p-4 text-[14px] text-ink-500">Keine Unterhaltungen.</li>}
          </ul>
        </Karte>

        {aktiv ? (
          <Karte
            titel={aktiv.titel}
            untertitel={aktivArt === "nutzer" && !admin ? "Wir antworten in der Regel innerhalb von zwei Werktagen." : aktiv.gegenueber && admin ? `Gesprächspartner: ${aktiv.gegenueber}` : undefined}
            aktion={aktiv.link && aktivArt !== "nutzer" ? <Link href={aktiv.link} className="inline-flex items-center gap-1 text-[13.5px] font-semibold text-ov-700 hover:text-ov-800">Zum Vorgang <ArrowUpRight aria-hidden="true" className="h-4 w-4" /></Link> : null}
          >
            <NachrichtenThread bezugArt={aktivArt} bezugId={aktivId} nachrichten={aktiv.nachrichten} hoehe="max-h-[56vh]" />
          </Karte>
        ) : (
          <Leer icon={MessagesSquare} titel="Unterhaltung auswählen" text="Wählen Sie links eine Unterhaltung. Neue Nachrichten an einzelne Nutzer schreiben Sie über „Nutzer & Protokoll“." />
        )}
      </div>
    </div>
  );
}
import { DokumentListe, DokumentUpload } from "@/components/Portal/Dokumente";
import { Karte, SeitenKopf } from "@/components/Portal/ui";
import { portalNutzer, istAdmin } from "@/lib/plattform/server/seite";
import { backend } from "@/lib/plattform/backend";

export const metadata = { title: "Dokumente" };

export default async function Dokumente() {
  const n = await portalNutzer();
  const admin = istAdmin(n);
  const dokumente = await backend().dokumente(n);
  return (
    <div>
      <SeitenKopf
        eyebrow="Dokumente"
        titel={admin ? "Alle Dokumente" : "Meine Dokumente"}
        text="Angebote, Verträge, Pläne und Ihre eigenen Uploads – zu jedem Vorgang. Unterlagen zu einer Fläche oder einem Projekt laden Sie direkt dort hoch."
      />
      <div className="grid gap-6 lg:grid-cols-[minmax(0,1.6fr)_minmax(0,1fr)]">
        <Karte titel={`${dokumente.length} ${dokumente.length === 1 ? "Dokument" : "Dokumente"}`}>
          <DokumentListe dokumente={dokumente} nutzerId={n.id} admin={admin} zeigeBezug leerText="Noch keine Dokumente vorhanden." />
        </Karte>
        {!admin && (
          <Karte titel="Allgemeines Dokument senden" untertitel="z. B. Vollmacht, Grundbuchauszug ohne Bezug zu einer Fläche">
            <DokumentUpload bezugArt="nutzer" bezugId={n.id} />
          </Karte>
        )}
      </div>
    </div>
  );
}

"use client";

// Nachrichtenverlauf zu einem Objekt (Vorgang, Fläche, Projekt, Interesse, Allgemein)
// mit Antwortfeld. Systemmeldungen (Statuswechsel, Uploads) erscheinen zentriert.

import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { Send, Info } from "lucide-react";
import { cn } from "@/components/ui/cn";
import { senden } from "@/lib/plattform/client";
import { datumZeit } from "@/lib/plattform/format";
import { textbereich, FehlerBox } from "./felder";
import KiNachrichtEntwurf from "./Ki/KiNachrichtEntwurf";
import { KiKennzeichnung } from "./Ki/KiBausteine";

export default function NachrichtenThread({ bezugArt, bezugId, nachrichten = [], leerText = "Noch keine Nachrichten. Schreiben Sie uns – wir antworten in der Regel innerhalb von zwei Werktagen.", platzhalter = "Ihre Nachricht …", hoehe = "max-h-[520px]" }) {
  const router = useRouter();
  const [text, setText] = useState("");
  const [laeuft, setLaeuft] = useState(false);
  const [fehler, setFehler] = useState("");
  const [kiMarke, setKiMarke] = useState(null); // Kennzeichnung eines Assistenten-Entwurfs im Antwortfeld
  const listeRef = useRef(null);

  useEffect(() => {
    const el = listeRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [nachrichten.length]);

  async function absenden(e) {
    e.preventDefault();
    if (text.trim().length < 2) return;
    setLaeuft(true);
    setFehler("");
    try {
      await senden("/api/portal/nachrichten", { body: { bezugArt, bezugId, text } });
      setText("");
      setKiMarke(null);
      router.refresh();
    } catch (err) {
      setFehler(err.message);
    } finally {
      setLaeuft(false);
    }
  }

  return (
    <div className="flex min-w-0 flex-col gap-4">
      <div ref={listeRef} className={cn("min-w-0 space-y-3 overflow-y-auto pr-1", hoehe)} aria-live="polite">
        {nachrichten.length === 0 && <p className="py-6 text-center text-[14px] text-ink-500">{leerText}</p>}
        {nachrichten.map((m) =>
          m.system ? (
            <div key={m.id} className="flex justify-center">
              <p className="inline-flex max-w-[92%] items-start gap-2 rounded-2xl bg-ink-50 px-3.5 py-2 text-[13px] leading-relaxed text-ink-600 ring-1 ring-inset ring-ink-100">
                <Info aria-hidden="true" className="mt-0.5 h-3.5 w-3.5 shrink-0 text-ink-400" />
                <span className="min-w-0 whitespace-pre-line break-words">
                  {m.text}
                  <span className="ml-1.5 whitespace-nowrap text-[11.5px] text-ink-400">{datumZeit(m.am)}</span>
                </span>
              </p>
            </div>
          ) : (
            <div key={m.id} className={cn("flex", m.eigene ? "justify-end" : "justify-start")}>
              <div className={cn("max-w-[85%] rounded-2xl px-4 py-3", m.eigene ? "rounded-br-md bg-navy-700 text-white" : "rounded-bl-md bg-white text-ink-800 ring-1 ring-ink-200")}>
                <p className={cn("text-[12px] font-semibold", m.eigene ? "text-white/70" : m.vonAdmin ? "text-ov-700" : "text-ink-500")}>
                  {m.eigene ? "Sie" : m.vonName}
                  {m.neu && !m.eigene && <span className="ml-2 rounded-full bg-ov-500 px-1.5 py-px text-[10.5px] font-bold uppercase text-white">neu</span>}
                </p>
                <p className="mt-1 whitespace-pre-line break-words text-[14.5px] leading-relaxed">{m.text}</p>
                <p className={cn("mt-1.5 text-[11.5px]", m.eigene ? "text-white/55" : "text-ink-400")}>{datumZeit(m.am)}</p>
              </div>
            </div>
          )
        )}
      </div>
      <form onSubmit={absenden} className="space-y-2">
        <label htmlFor={`antwort-${bezugArt}-${bezugId}`} className="sr-only">Nachricht</label>
        <textarea
          id={`antwort-${bezugArt}-${bezugId}`}
          rows={3}
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) absenden(e);
          }}
          placeholder={platzhalter}
          maxLength={5000}
          className={textbereich}
        />
        <FehlerBox>{fehler || kiMarke?.fehler}</FehlerBox>
        {kiMarke?.modus && text.trim() && <KiKennzeichnung modus={kiMarke.modus} hinweis={kiMarke.hinweis} />}
        <div className="flex items-center justify-between gap-3">
          <p className="hidden text-[12px] text-ink-400 sm:block">Strg + Enter zum Senden</p>
          <KiNachrichtEntwurf bezugArt={bezugArt} bezugId={bezugId} text={text} setText={setText} onKennzeichnung={setKiMarke} />
          <button
            type="submit"
            disabled={laeuft || text.trim().length < 2}
            className="ml-auto inline-flex h-10 items-center gap-2 rounded-full bg-ov-600 px-5 text-[14px] font-semibold text-white transition-colors hover:bg-ov-700 disabled:opacity-50"
          >
            <Send aria-hidden="true" className="h-4 w-4" />
            {laeuft ? "Wird gesendet …" : "Senden"}
          </button>
        </div>
      </form>
    </div>
  );
}
"use client";

// Dokumentliste mit Download, Löschen (eigene Uploads) und optionalem Upload.
// Prüfung von Typ (PDF/JPG/PNG an den ersten Bytes) und Größe (≤ 10 MB) erfolgt serverseitig;
// hier nur Vorprüfung für schnelle Rückmeldung.

import { useRef, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { Download, FileImage, FileText, Trash2, UploadCloud } from "lucide-react";
import { cn } from "@/components/ui/cn";
import { hochladen, senden } from "@/lib/plattform/client";
import { DOKUMENT_KATEGORIEN, UPLOAD } from "@/lib/plattform/konstanten";
import { datum, dateigroesse } from "@/lib/plattform/format";
import { auswahlfeld, FehlerBox, ErfolgBox } from "./felder";

export function DokumentListe({ dokumente = [], nutzerId, admin = false, zeigeBezug = false, leerText = "Noch keine Dokumente." }) {
  const router = useRouter();
  const [fehler, setFehler] = useState("");

  async function loeschen(d) {
    if (!window.confirm(`„${d.name}“ wirklich löschen?`)) return;
    try {
      await senden(`/api/portal/dokumente/${d.id}`, { method: "DELETE" });
      router.refresh();
    } catch (e) {
      setFehler(e.message);
    }
  }

  if (!dokumente.length) return <p className="text-[14px] text-ink-500">{leerText}</p>;
  return (
    <div className="space-y-2">
      <FehlerBox>{fehler}</FehlerBox>
      <ul className="divide-y divide-ink-100">
        {dokumente.map((d) => {
          const Icon = d.mime === "application/pdf" ? FileText : FileImage;
          return (
            <li key={d.id} className="flex items-center gap-3 py-3">
              <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-navy-50 text-navy-700">
                <Icon aria-hidden="true" className="h-5 w-5" />
              </span>
              <div className="min-w-0 flex-1">
                <a href={`/api/portal/dokumente/${d.id}?anzeigen=1`} target="_blank" rel="noopener" className="block truncate text-[14.5px] font-semibold text-ink-900 hover:text-ov-700">
                  {d.name}
                </a>
                <p className="truncate text-[12.5px] text-ink-500">
                  {DOKUMENT_KATEGORIEN[d.kategorie] || d.kategorie} · {dateigroesse(d.groesse)} · {datum(d.am)}
                  {zeigeBezug && d.bezugTitel && (
                    <>
                      {" · "}
                      {d.bezugLink ? <Link href={d.bezugLink} className="underline underline-offset-2 hover:text-ov-700">{d.bezugTitel}</Link> : d.bezugTitel}
                    </>
                  )}
                </p>
              </div>
              <a href={`/api/portal/dokumente/${d.id}`} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-ink-600 hover:bg-ink-100 hover:text-ink-900" aria-label={`${d.name} herunterladen`}>
                <Download aria-hidden="true" className="h-4 w-4" />
              </a>
              {(admin || d.hochgeladenVon === nutzerId) && (
                <button type="button" onClick={() => loeschen(d)} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-ink-500 hover:bg-ink-100 hover:text-ink-900" aria-label={`${d.name} löschen`}>
                  <Trash2 aria-hidden="true" className="h-4 w-4" />
                </button>
              )}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

export function DokumentUpload({ bezugArt, bezugId, kategorien = ["allgemein"], hinweis }) {
  const router = useRouter();
  const inputRef = useRef(null);
  const [kategorie, setKategorie] = useState(kategorien[0]);
  const [laeuft, setLaeuft] = useState(false);
  const [fehler, setFehler] = useState("");
  const [erfolg, setErfolg] = useState("");
  const [ziehen, setZiehen] = useState(false);

  async function dateienVerarbeiten(liste) {
    setFehler("");
    setErfolg("");
    const dateien = Array.from(liste || []).slice(0, 5);
    if (!dateien.length) return;
    for (const f of dateien) {
      if (!UPLOAD.typen[f.type]) return setFehler(`„${f.name}“: erlaubt sind PDF, JPG und PNG.`);
      if (f.size > UPLOAD.maxBytes) return setFehler(`„${f.name}“ ist größer als 10 MB.`);
    }
    setLaeuft(true);
    try {
      for (const f of dateien) await hochladen(f, { bezugArt, bezugId, kategorie });
      setErfolg(dateien.length === 1 ? "Dokument hochgeladen." : `${dateien.length} Dokumente hochgeladen.`);
      router.refresh();
    } catch (e) {
      setFehler(e.message);
    } finally {
      setLaeuft(false);
      if (inputRef.current) inputRef.current.value = "";
    }
  }

  return (
    <div className="space-y-3">
      {kategorien.length > 1 && (
        <div>
          <label htmlFor={`kat-${bezugId}`} className="mb-1.5 block text-[13px] font-semibold text-ink-700">Ablage</label>
          <select id={`kat-${bezugId}`} value={kategorie} onChange={(e) => setKategorie(e.target.value)} className={cn(auswahlfeld, "h-11")}>
            {kategorien.map((k) => (
              <option key={k} value={k}>{DOKUMENT_KATEGORIEN[k]}</option>
            ))}
          </select>
        </div>
      )}
      <label
        onDragOver={(e) => {
          e.preventDefault();
          setZiehen(true);
        }}
        onDragLeave={() => setZiehen(false)}
        onDrop={(e) => {
          e.preventDefault();
          setZiehen(false);
          dateienVerarbeiten(e.dataTransfer.files);
        }}
        className={cn(
          "flex cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed px-4 py-6 text-center transition-colors has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ov-500",
          ziehen ? "border-ov-500 bg-ov-50" : "border-ink-200 bg-sand-50 hover:border-ov-300"
        )}
      >
        <UploadCloud aria-hidden="true" className="h-7 w-7 text-ov-600" />
        <span className="mt-2 text-[14px] font-semibold text-ink-800">{laeuft ? "Wird hochgeladen …" : "Datei wählen oder hierher ziehen"}</span>
        <span className="mt-0.5 text-[12.5px] text-ink-500">{hinweis || "PDF, JPG oder PNG, höchstens 10 MB"}</span>
        <input ref={inputRef} type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" multiple className="sr-only" disabled={laeuft} onChange={(e) => dateienVerarbeiten(e.target.files)} />
      </label>
      <FehlerBox>{fehler}</FehlerBox>
      <ErfolgBox>{erfolg}</ErfolgBox>
    </div>
  );
}

