// src/lib/plattform/server/monatsbericht.js
//
// Monatsbericht des Backoffice als PDF (gemeinsamer PDF-Erzeuger server/pdf.js, Markenfarben wie
// das Exposé) und Bericht als CSV (Excel-DE über csv.js). Daten: Operation `bericht` des Backends.

import { PdfDokument, umbrechen } from "./pdf";
import { csvWert } from "../csv";
import { LAENDER } from "../konstanten";
import { fmt } from "@/lib/rechner/annahmen";

const F = {
  navy950: "#03122b", navy900: "#041d42", navy700: "#003473", navy500: "#1f5aa1", ov300: "#aed083", ov500: "#669933", ov600: "#558227",
  ink900: "#151a24", ink700: "#394050", ink500: "#6b7486", ink400: "#97a0b0", ink200: "#dfe3ea", ink100: "#eef0f4", ink50: "#f7f8fa", sand100: "#f5f3ea", sun400: "#ffc53d", weiss: "#ffffff",
};
const LAND_FARBE = { DE: F.ov500, AT: F.navy500, CH: F.sun400 };
const RAND = 44;
const FUSS = 58;

const eur = (x) => (Number.isFinite(x) ? `${fmt(Math.round(x))} €` : "–");
const pct = (x) => (Number.isFinite(x) ? `${fmt(x * 100, 0)} %` : "–");
const zahl = (x, s = 0) => (Number.isFinite(Number(x)) && x !== null ? fmt(Number(x), s) : "–");
const MONATE = ["Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August", "September", "Oktober", "November", "Dezember"];
export const monatName = (m) => (/^\d{4}-\d{2}$/.test(m || "") ? `${MONATE[Number(m.slice(5)) - 1]} ${m.slice(0, 4)}` : m);

function delta(jetzt, vorher, format = (x) => zahl(x)) {
  if (!Number.isFinite(jetzt) || !Number.isFinite(vorher)) return "";
  const d = jetzt - vorher;
  if (Math.abs(d) < 1e-9) return "± 0 ggü. Vormonat";
  return `${d > 0 ? "+" : "–"}${format(Math.abs(d))} ggü. Vormonat`;
}

export function monatsberichtPdf({ bericht: b, vormonat: vb = null, monat, ersteller = "" }) {
  const doc = new PdfDokument({ titel: `Monatsbericht Backoffice ${monatName(monat)}`, thema: "Interner Monatsbericht (vertraulich)" });
  const B = doc.breite - 2 * RAND;
  let s = null;
  let y = 0;

  const neueSeite = (erste = false) => {
    s = doc.seite();
    if (erste) {
      s.rechteck(0, 0, doc.breite, 118, F.navy950);
      s.text(RAND, 44, "ÖkoInvest", { groesse: 19, fett: true, farbe: F.weiss });
      s.text(doc.breite - RAND, 44, "MONATSBERICHT BACKOFFICE", { groesse: 8.5, fett: true, farbe: F.ov300, ausrichtung: "rechts", zeichenabstand: 1 });
      s.text(RAND, 84, monatName(monat), { groesse: 24, fett: true, farbe: F.weiss });
      s.text(RAND, 104, `Zeitraum ${b.zeitraum.von.split("-").reverse().join(".")} – ${b.zeitraum.bis.split("-").reverse().join(".")} · Vertraulich, nur für den internen Gebrauch`, { groesse: 9, farbe: F.ov300 });
      y = 146;
    } else {
      s.rechteck(0, 0, doc.breite, 32, F.navy950);
      s.text(RAND, 21, "ÖkoInvest", { groesse: 10, fett: true, farbe: F.weiss });
      s.text(doc.breite - RAND, 21, `Monatsbericht ${monatName(monat)}`, { groesse: 8.5, farbe: F.ov300, ausrichtung: "rechts" });
      y = 60;
    }
  };
  const platz = (h) => {
    if (y + h > doc.hoehe - FUSS - 6) neueSeite();
  };
  const ueberschrift = (t, sub = "") => {
    platz(64);
    y += 12;
    s.text(RAND, y, t, { groesse: 12.5, fett: true, farbe: F.navy900 });
    s.rechteck(RAND, y + 5, 24, 2.2, F.ov500);
    if (sub) s.text(doc.breite - RAND, y, sub, { groesse: 8.5, farbe: F.ink500, ausrichtung: "rechts" });
    y += 22;
  };
  const tabelle = (spalten, zeilen, { leer = "Keine Daten im Zeitraum." } = {}) => {
    const summe = spalten.reduce((x, c) => x + c.b, 0);
    const breiten = spalten.map((c) => (c.b / summe) * B);
    platz(22 + Math.min(zeilen.length, 3) * 17);
    s.rechteck(RAND, y - 11, B, 17, F.ink50);
    let x = RAND;
    spalten.forEach((c, i) => {
      s.text(c.rechts ? x + breiten[i] - 6 : x + 6, y + 1, c.label, { groesse: 8, fett: true, farbe: F.ink500, ausrichtung: c.rechts ? "rechts" : "links" });
      x += breiten[i];
    });
    y += 18;
    if (!zeilen.length) {
      s.text(RAND + 6, y, leer, { groesse: 9, farbe: F.ink500 });
      y += 16;
      return;
    }

  inhalt() {
    return this.ops.join("\n");
  }
}

export class PdfDokument {
  constructor({ titel = "Dokument", autor = "ÖkoInvest GmbH", thema = "" } = {}) {
    this.breite = A4.breite;
    this.hoehe = A4.hoehe;
    this.titel = titel;
    this.autor = autor;
    this.thema = thema;
    this.seiten = [];
    this.bilder = []; // Bilder (Image-XObjects) für Seite.bild()
  }

  /** Ressourcenname eines Bildes (jedes Bild wird einmal eingebettet) */
  bildName(bild) {
    let i = this.bilder.indexOf(bild);
    if (i < 0) i = this.bilder.push(bild) - 1;
    return `Im${i + 1}`;
  }

  seite() {
    const s = new Seite(this);
    this.seiten.push(s);
    return s;
  }

  /** Fertiges PDF als Buffer */
  alsBuffer() {
    if (!this.seiten.length) this.seite();
    const objekte = [];
    const neu = (inhalt) => objekte.push(inhalt) && objekte.length;
    const katalog = neu(null);
    const seitenbaum = neu(null);
    const f1 = neu("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
    const f2 = neu("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");
    // Bilder (Seite.bild) als Image-XObjects: FlateDecode, Alphakanal als weiche Maske (SMask)
    const bildRefs = (this.bilder || []).map((b, i) => {
      const maske = b.alpha
        ? neu(`<< /Type /XObject /Subtype /Image /Width ${b.breite} /Height ${b.hoehe} /ColorSpace /DeviceGray /BitsPerComponent 8 /Filter /FlateDecode /Length ${b.alpha.length} >>\nstream\n${b.alpha.toString("latin1")}\nendstream`)
        : null;
      const nr = neu(
        `<< /Type /XObject /Subtype /Image /Width ${b.breite} /Height ${b.hoehe} /ColorSpace /${b.farben === 1 ? "DeviceGray" : "DeviceRGB"} /BitsPerComponent 8 /Filter /FlateDecode${maske ? ` /SMask ${maske} 0 R` : ""} /Length ${b.daten.length} >>\nstream\n${b.daten.toString("latin1")}\nendstream`
      );
      return `/Im${i + 1} ${nr} 0 R`;
    });
    const xobjekte = bildRefs.length ? ` /XObject << ${bildRefs.join(" ")} >>` : "";
    const kinder = [];
    for (const s of this.seiten) {
      const inhalt = s.inhalt();
      const strom = neu(`<< /Length ${Buffer.byteLength(inhalt, "latin1")} >>\nstream\n${inhalt}\nendstream`);
      kinder.push(
        neu(`<< /Type /Page /Parent ${seitenbaum} 0 R /MediaBox [0 0 ${zahl(this.breite)} ${zahl(this.hoehe)}] /Resources << /Font << /F1 ${f1} 0 R /F2 ${f2} 0 R >>${xobjekte} >> /Contents ${strom} 0 R >>`)
      );
    }
    objekte[katalog - 1] = `<< /Type /Catalog /Pages ${seitenbaum} 0 R >>`;
    objekte[seitenbaum - 1] = `<< /Type /Pages /Kids [${kinder.map((k) => `${k} 0 R`).join(" ")}] /Count ${kinder.length} >>`;
    const d = new Date();
    const pdfDatum = `D:${d.getUTCFullYear()}${String(d.getUTCMonth() + 1).padStart(2, "0")}${String(d.getUTCDate()).padStart(2, "0")}${String(d.getUTCHours()).padStart(2, "0")}${String(d.getUTCMinutes()).padStart(2, "0")}${String(d.getUTCSeconds()).padStart(2, "0")}Z`;
    const info = neu(`<< /Title ${literal(this.titel)} /Author ${literal(this.autor)} /Subject ${literal(this.thema)} /Producer (OekoInvest Plattform) /CreationDate (${pdfDatum}) >>`);

    let pdf = "%PDF-1.4\n%\xe2\xe3\xcf\xd3\n";
    const offsets = [];
    objekte.forEach((o, i) => {
      offsets.push(Buffer.byteLength(pdf, "latin1"));
      pdf += `${i + 1} 0 obj\n${o}\nendobj\n`;
    });
    const xref = Buffer.byteLength(pdf, "latin1");
    pdf += `xref\n0 ${objekte.length + 1}\n0000000000 65535 f \n`;
    pdf += offsets.map((o) => `${String(o).padStart(10, "0")} 00000 n \n`).join("");
    pdf += `trailer\n<< /Size ${objekte.length + 1} /Root ${katalog} 0 R /Info ${info} 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
    return Buffer.from(pdf, "latin1");
  }
}

