    kategorie: String(fd.get("kategorie") || "allgemein"),
    checkliste: String(fd.get("checkliste") || "").slice(0, 40),
    name: datei.name || `dokument.${UPLOAD.typen[mime]}`,
    mime,
    daten,
  });
  return { ok: true, dokument };
});
