          <span className={cn("flex h-9 w-9 shrink-0 items-center justify-center rounded-xl", dunkel ? "bg-white/10 text-ov-300" : "bg-ov-50 text-ov-600")}>
            <Icon aria-hidden="true" className="h-[18px] w-[18px]" />
