        { label: "Text", wert: "text" }, { label: "Nutzer", wert: "nutzer" }, { label: "Nutzer-ID", wert: "nutzerId" }, { label: "Eintrag", wert: "id" }, { label: "Hash", wert: "hash" }, { label: "Vorgänger-Hash", wert: "prevHash" },
      ],
