          const iw = innerWidth;
          const breit = [];
          if (document.documentElement.scrollWidth > iw + 1) {
            for (const el of document.querySelectorAll("body *")) {
              const r = el.getBoundingClientRect();
              if (r.right > iw + 1 && r.width > 0) {
                let q = el.parentElement, clip = false;
